export const VISUALS: readonly GalleryVisual[] = [
  {"slug":"cet-errors-add","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"units-and-measurement","chapterName":"Units and Measurement","subtopicSlug":"cetp-um-errors","subtopicTitle":"Units and Errors in Measurement","conceptSlug":"cetp-um-absolute-errors","conceptName":"Means, Absolute Errors and Kinds of Error","line":"Several readings are reported as their mean, with the mean of their absolute deviations as the error: 30, 32, 35, 35 s give 33 ± 2 s. In a sum or a difference the absolute errors ADD, never subtract: (82.3 ± 0.3) − (38.6 ± 0.2) = 43.7 ± 0.5. Systematic errors push every reading the same way (a badly calibrated thermometer, a zero error); random errors scatter them (a fluctuating supply). Units follow from formulas: L/R is the time constant of an LR circuit, measured in seconds.","pyqExampleId":"288160e2-6c6f-46a4-aabc-c4c2779fd4df","badge":"picture","interactive":false},
  {"slug":"vector-addition","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"motion-in-a-plane","chapterName":"Motion in a Plane","subtopicSlug":"cetp-mp-vectors","subtopicTitle":"Vectors: Addition and Products","conceptSlug":"cetp-mp-vector-addition","conceptName":"Adding Vectors","line":"Add component by component; the unit vector along the result is the result divided by its magnitude. Geometrically, R² = A² + B² + 2AB cos θ. Three vectors form a triangle only if they close — one equals the sum of the other two — which also means they lie in a plane. If the sum of two vectors is perpendicular to their difference, (A + B)·(A − B) = A² − B² = 0, so they have equal magnitudes. A condition such as 'A + 2B is perpendicular to A' gives A + 2B cos θ = 0, which substituted into R² simplifies directly.","pyqExampleId":"4c9882af-bf3a-4bf6-8548-00b936c3356d","badge":"try","interactive":true},
  {"slug":"kin-velocity-time-graph","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"motion-in-a-plane","chapterName":"Motion in a Plane","subtopicSlug":"cetp-mp-kinematics","subtopicTitle":"Equations of Motion and Motion Graphs","conceptSlug":"cetp-mp-graphs-calculus","conceptName":"Motion Graphs and Calculus","line":"Velocity is dx/dt and acceleration dv/dt; going the other way, integrate. On an x–t graph a flat line means rest and a straight sloping line uniform velocity; on a v–t graph the slope is acceleration and the area is displacement. Distance counts every area as positive, displacement subtracts the parts below the axis. On an a–t graph the area is the change in velocity. In two dimensions, find vₓ and v_y separately and combine: x = at², y = bt² gives speed 2t√(a² + b²).","pyqExampleId":"ca59be6b-e5a4-4879-a7dd-d41029ed81be","badge":"picture","interactive":false},
  {"slug":"kin-projectile-parabola","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"motion-in-a-plane","chapterName":"Motion in a Plane","subtopicSlug":"cetp-mp-projectile","subtopicTitle":"Projectiles","conceptSlug":"cetp-mp-projectile","conceptName":"Time of Flight, Height and Range","line":"Split the motion: horizontally nothing acts, so uₓ = u cos θ stays; vertically it is free fall from u sin θ. At the top only the horizontal velocity remains, so the kinetic energy there is E cos²θ, and gravity acts as the centripetal force on a path of radius u²cos²θ/g. Setting H = R gives tan θ = 4. A ball thrown upward that passes height h at t₁ on the way up and lands t₂ later has h = ½gt₁t₂. From a tower, solve the vertical equation for the time first, taking care whether the throw is above or below the horizontal, then multiply by the horizontal speed.","pyqExampleId":"b771e9ee-8aff-445b-a53c-8db464e2e3a1","badge":"picture","interactive":false},
  {"slug":"lmf-free-body-diagram","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"laws-of-motion","chapterName":"Laws of Motion","subtopicSlug":"cetp-lm-newton","subtopicTitle":"Newton's Laws: Lifts, Pulleys, Circles and Power","conceptSlug":"cetp-lm-newton-applications","conceptName":"Lifts, Blocks in Contact and Pulleys","line":"Draw each body and add the forces along its motion. A person in a lift feels the floor's push N = m(g + a) going up with acceleration a, m(g − a) going down; a spring balance reads the same way. Blocks pushed together share one acceleration F/(total mass), and the push on the far block is its own mass times that acceleration. In an Atwood machine, the net pull is the difference of the weights and the mass to accelerate is the total. Only frames moving at constant velocity are inertial: an accelerating train, a merry-go-round and a plane taking off are not. Gravity acts without contact; friction, normal reaction and viscosity need it.","pyqExampleId":"42ec956f-c7c7-4003-b434-f1d387f6ebbe","badge":"picture","interactive":false},
  {"slug":"imat-collision-momentum","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"laws-of-motion","chapterName":"Laws of Motion","subtopicSlug":"cetp-lm-momentum","subtopicTitle":"Impulse, Momentum and Collisions","conceptSlug":"cetp-lm-collisions","conceptName":"Collisions and the Coefficient of Restitution","line":"Momentum is conserved in every collision; kinetic energy only in an elastic one. The coefficient of restitution e = (speed of separation)/(speed of approach) is 1 when elastic and 0 when the bodies stick. Two equations — momentum and restitution — give both final velocities. A body that stops after hitting a stationary one of mass M gives e = m/M. Bodies that stick share one velocity, found component by component when they move at right angles. A ball dropped onto a surface rebounds to e²h.","pyqExampleId":"29b6cb1b-e0b7-499e-92c6-845d805c6287","badge":"try","interactive":true},
  {"slug":"imat-moments-seesaw","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"laws-of-motion","chapterName":"Laws of Motion","subtopicSlug":"cetp-lm-equilibrium","subtopicTitle":"Equilibrium and the Centre of Mass","conceptSlug":"cetp-lm-equilibrium","conceptName":"Moments, Reactions and the Centre of Mass","line":"For balance, take moments about a point where an unknown force acts, so it drops out. A metre scale on a wedge at its centre balances when w × (its distance) = W × (the other distance). A rod on two knife-edges r apart, with its weight x from A, has reaction W(r − x)/r at A. At a knot held by strings the vector sum of the tensions is zero: two equal tensions T at θ to the vertical hold up 2T cos θ. The centre of mass of two particles is at (m₁x₁ + m₂x₂)/(m₁ + m₂), on the line between them; to keep it fixed, moving m₁ by d toward it must be balanced by moving m₂ by (m₁/m₂)d toward it too.","pyqExampleId":"c81ee95c-9782-419e-b08b-ab651fe29d0a","badge":"try","interactive":true},
  {"slug":"cet-g-height-depth","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"gravitation","chapterName":"Gravitation","subtopicSlug":"cetp-gr-variation-of-g","subtopicTitle":"How g Changes: Height, Depth, Density and Spin","conceptSlug":"cetp-gr-altitude-depth","conceptName":"Height and Depth","line":"At height h, g_h = g R²/(R + h)²: at h = R it is g/4, at 2R it is g/9. The small-height form g(1 − 2h/R) is for h much smaller than R. At depth d, only the sphere of radius R − d below still pulls, so g_d = g(1 − d/R), halved at R/2 and zero at the centre. A pendulum's period goes as 1/√g, so it slows at a height and at a depth; its frequency goes as √g. A capillary rise goes as 1/g, so it grows in a mine. 'Reduced BY 64%' means g becomes 36% of its value.","pyqExampleId":"4b9b76d7-de1a-4986-b98b-87dcb3cbb9c7","badge":"try","interactive":true},
  {"slug":"cet-cut-spring","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"mechanical-properties-of-solids","chapterName":"Mechanical Properties of Solids","subtopicSlug":"cetp-ms-springs","subtopicTitle":"Springs and Elastic Energy","conceptSlug":"cetp-ms-springs","conceptName":"Spring Constant, Series Springs and Elastic Energy","line":"A spring obeys F = kx and stores U = ½kx², so three times the stretch stores nine times the energy. A spring's constant is inversely proportional to its length: cut a spring of constant K into pieces L₁ = NL₂, and the longer piece has constant K(N + 1)/N. Two springs hung in a chain carry the same force and add their extensions, f/k₁ + f/k₂. A ball of mass m dropped from height s onto a spring platform that sinks h loses mg(s + h) of potential energy into ½kh².","pyqExampleId":"ebe4c03c-0c80-4e8e-b8f3-c279b3fce0d9","badge":"try","interactive":true},
  {"slug":"cet-wien-peak","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"thermal-properties-of-matter","chapterName":"Thermal Properties of Matter","subtopicSlug":"cetp-th-radiation","subtopicTitle":"Radiation: Stefan, Wien and Newton's Law of Cooling","conceptSlug":"cetp-th-wien-law","conceptName":"Wien's Law: the Peak Moves With Temperature","line":"A hotter body's spectrum peaks at a shorter wavelength: λ_mT = b, about 2.9 × 10⁻³ m K. So the frequency at the peak is proportional to T — a straight line through the origin on a ν_m–T graph. Many questions pair it with Stefan's law: if the peak wavelength falls to λ/3, the temperature has tripled and the emissive power has risen 81 times. For bodies of different sizes, combine the two as P ∝ R²/λ_m⁴.","pyqExampleId":"a3c2085b-b95c-466b-9096-9e79f6c2c938","badge":"try","interactive":true},
  {"slug":"cet-doppler-wavefronts","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"sound","chapterName":"Sound","subtopicSlug":"cetp-sd-doppler","subtopicTitle":"The Doppler Effect","conceptSlug":"cetp-sd-doppler-formula","conceptName":"The Doppler Formula","line":"Write f′ = f(v + v_o)/(v − v_s) with both speeds positive when they bring source and observer closer; flip a sign for each one moving apart. An observer approaching at v/5 hears 6/5 of the pitch, 20% more. A source approaching at v/10 gives 10/9. The same speed does more when the source moves, because it squeezes the waves: at 50 m/s with v = 330, a moving source gives 330/280 = 1.18f, a moving observer 380/330 = 1.15f. A source receding at v halves the pitch; an observer must approach at 2v to triple it. Frequency rises, so the wavelength the observer measures falls.","pyqExampleId":"20660e8a-a8c5-40eb-ace8-65b651a31686","badge":"picture","interactive":false},
  {"slug":"opt-concave-mirror-rays","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"ray-optics","chapterName":"Optics (Ray)","subtopicSlug":"cetp-ro-mirrors","subtopicTitle":"Mirrors","conceptSlug":"cetp-ro-mirrors","conceptName":"The Mirror Formula and Plane Mirrors","line":"With the Cartesian sign convention the mirror formula is 1/v + 1/u = 1/f and the magnification is −v/u. A real image n times the size of the object means v = nu (both in front), so u = (n + 1)f/n. For a convex mirror, the formula turns an image position into an object position, so a moving image gives the object's speed. A plane mirror has magnification +1. Two plane mirrors at θ form 360°/θ − 1 images: three images at 90°. Covering half a mirror leaves every point of the image formed by the rest of the mirror, so the image is complete but dimmer.","pyqExampleId":"d54603d9-9feb-4994-8f69-e0edf6ed23af","badge":"picture","interactive":false},
  {"slug":"imat-snell-refraction","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"ray-optics","chapterName":"Optics (Ray)","subtopicSlug":"cetp-ro-refraction","subtopicTitle":"Refraction, Apparent Depth and Total Internal Reflection","conceptSlug":"cetp-ro-snell","conceptName":"Snell's Law and the Refractive Index","line":"The refractive index μ = c/v says how much light slows; a 20% slower speed means μ = 1/0.8 = 1.25. Snell's law, sin i = μ sin r, bends the ray toward the normal; for small angles i ≈ μr, so the deviation i − r is i(1 − 1/μ). Between two media the relative index is the ratio of speeds. The optical path μd is the distance light would cover in vacuum in the same time, so equal times through two materials mean equal μd. When i = 2r, μ = sin 2r / sin r = 2 cos r.","pyqExampleId":"32f3fab2-9278-4fe5-b598-b89b98430c05","badge":"try","interactive":true},
  {"slug":"opt-refraction-tir","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"ray-optics","chapterName":"Optics (Ray)","subtopicSlug":"cetp-ro-refraction","subtopicTitle":"Refraction, Apparent Depth and Total Internal Reflection","conceptSlug":"cetp-ro-total-internal-reflection","conceptName":"Total Internal Reflection","line":"Going from denser to rarer, the ray bends away from the normal, and at the critical angle sin C = 1/μ (or μ₂/μ₁ between two media) it grazes the surface; beyond that, all the light reflects. Two conditions, then: denser to rarer, and i > C. Blue light has a higher index than red, so a smaller critical angle: when green is just totally reflected, violet, indigo and blue are too. Glass to air has the smallest critical angle among common pairs. A source at depth h is hidden by a floating disc of radius h tan C = h/√(μ² − 1). Mirages, a diamond's sparkle and optical fibres rely on it; the apparent depth of a pond does not.","pyqExampleId":"71c369f4-14fb-4e7f-a43d-ff5617feafa0","badge":"picture","interactive":false},
  {"slug":"opt-convex-lens-rays","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"ray-optics","chapterName":"Optics (Ray)","subtopicSlug":"cetp-ro-lenses","subtopicTitle":"Lenses: the Lens Formula, the Lensmaker's Equation and Combinations","conceptSlug":"cetp-ro-lens-formula","conceptName":"The Lens Formula and Magnification","line":"With the Cartesian convention, 1/v − 1/u = 1/f and m = v/u. For a real image n times the size of the object, v = −nu (opposite sides), so the object distance is f(1 + 1/n) and the image distance f(n + 1). The object and its real image are closest, 4f apart, when both sit at 2f. An air bubble in water is a double-convex lens of the rarer medium inside the denser, so it diverges. Chromatic aberration — colours focusing at different points — comes from dispersion in the lens. At a single spherical surface, μ₂/v − μ₁/u = (μ₂ − μ₁)/R.","pyqExampleId":"29c78552-cbec-419a-b749-2b1585115dc7","badge":"picture","interactive":false},
  {"slug":"imat-circular-motion","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"rotational-dynamics","chapterName":"Rotational Dynamics","subtopicSlug":"cetp-circular-kinematics","subtopicTitle":"Kinematics of Circular Motion","conceptSlug":"cetp-angular-velocity","conceptName":"Angular Velocity, Linear Speed and Centripetal Acceleration","line":"Every point of a turning body sweeps the same angle in the same time, so the angular velocity is shared; the linear speed grows with the distance from the axis. Two bodies with the same period therefore have the same ω, and their speeds and centripetal accelerations are in the ratio of their radii.","pyqExampleId":"75c429b2-cfec-4572-8b54-760fd192a393","badge":"try","interactive":true},
  {"slug":"cet-rolling-energy-split","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"rotational-dynamics","chapterName":"Rotational Dynamics","subtopicSlug":"cetp-rolling","subtopicTitle":"Rotational Kinetic Energy and Rolling Motion","conceptSlug":"cetp-rolling-energy","conceptName":"How a Rolling Body's Energy Splits","line":"A body rolling without slipping moves and spins at once, with v = Rω. Its total energy is ½mv²(1 + k²/R²). A ring puts as much into spinning as into moving; a solid sphere puts only 2 parts in 7 into spinning.","pyqExampleId":"b48425b7-7a6b-4f04-8bb3-01f1378d4677","badge":"picture","interactive":false},
  {"slug":"fluid-pressure-depth","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"mechanical-properties-of-fluids","chapterName":"Mechanical Properties of Fluids","subtopicSlug":"cetp-fl-pressure","subtopicTitle":"Pressure with Depth and Buoyancy","conceptSlug":"cetp-fl-pressure-depth-bubble","conceptName":"Pressure with Depth, and the Rising Bubble","line":"Every metre of water adds ρg of pressure. A bubble at the bottom of a lake carries the atmosphere plus the water above it; at the surface, only the atmosphere. At constant temperature PV stays fixed, so if the volume grows eight times (radius or diameter doubles) the pressure at the bottom was eight times the surface pressure — the water supplied seven of those eight parts. Write the atmosphere as a column of water H (or of mercury h, relative density ρ, which is hρ of water), and the depth is 7H.","pyqExampleId":"b4c3d2d5-7b55-4c97-8f47-44046aeb2458","badge":"picture","interactive":false},
  {"slug":"archimedes-floating-block","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"mechanical-properties-of-fluids","chapterName":"Mechanical Properties of Fluids","subtopicSlug":"cetp-fl-pressure","subtopicTitle":"Pressure with Depth and Buoyancy","conceptSlug":"cetp-fl-buoyancy-sinking","conceptName":"Upthrust, and How Deep a Light Body Sinks","line":"A body dropped from height h enters the liquid at √(2gh). Inside, the upthrust σVg beats its weight ρVg, so the net upward force (σ − ρ)Vg decelerates it at (σ − ρ)g/ρ. It sinks until that deceleration has used up its speed: depth = v²/2a = hρ/(σ − ρ). Then it rises and floats. The body only goes deep when its density is close to the liquid's.","pyqExampleId":"57b5b433-777b-4b90-a886-de05ff0fa69d","badge":"picture","interactive":false},
  {"slug":"cet-continuity-pipe","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"mechanical-properties-of-fluids","chapterName":"Mechanical Properties of Fluids","subtopicSlug":"cetp-fl-flow","subtopicTitle":"Streamline Flow: Continuity, Bernoulli and Torricelli","conceptSlug":"cetp-fl-continuity","conceptName":"Continuity: Narrow Pipe, Faster Flow","line":"Water cannot pile up in a pipe, so the volume flow rate Q = Av is the same everywhere along it. A pipe of a third the radius has a ninth the area, so the water moves nine times faster. The same rule links a pipe to a nozzle (d√(V/V₁)), a hose to a sprinkler with n holes (v' = R²v/(nr²)), and a tap to the falling water level in a tank (dh/dt = a v/A). Streamline flow means the velocity at any fixed point does not change with time and the layers stay parallel.","pyqExampleId":"55e31f3c-e6a9-4fd9-a197-3b15067c492b","badge":"try","interactive":true},
  {"slug":"imat-boyle-curve","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"kinetic-theory-of-gases","chapterName":"Kinetic Theory of Gases","subtopicSlug":"cetp-kt-gas-laws","subtopicTitle":"The Gas Laws and the Ideal Gas Equation","conceptSlug":"cetp-kt-gas-laws","conceptName":"One Law at a Time","line":"Hold one quantity fixed and the other two are tied. At constant temperature PV is constant, so a 5% smaller volume needs pressure multiplied by 20/19 — 5.26% more, not 5%. At constant volume P ∝ T in kelvin, so a 2.5% rise in pressure for a 4 K rise means the gas started at 160 K. Combining them, P₁V₁/T₁ = P₂V₂/T₂. A real gas behaves most like an ideal one at low pressure and high temperature, where the molecules are far apart and fast. The force a gas exerts on a closed container's wall is its pressure times the area, so it goes as T to the first power.","pyqExampleId":"bebf2e49-e45d-4b7d-b210-2be8b04bdea9","badge":"try","interactive":true},
  {"slug":"ht-pv-process-diagram","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"thermodynamics","chapterName":"Thermodynamics","subtopicSlug":"cetp-td-processes","subtopicTitle":"The Four Processes and the Adiabatic Relations","conceptSlug":"cetp-td-process-identification","conceptName":"Recognising Each Process","line":"Each process fixes one quantity. Isothermal: T constant, so ΔU = 0, PV = constant, a hyperbola on P–V, and all heat becomes work. Adiabatic: no heat exchanged, the system insulated, PV^γ = constant, and a steeper curve than the isothermal through the same point; the temperature changes. Isobaric: P constant, a horizontal line on P–V. Isochoric: V constant, a vertical line on P–V, no work, dQ = dU. A process PV^n = constant with zero specific heat must be adiabatic, so n = γ. On a p–T graph an isothermal is a vertical line.","pyqExampleId":"9528bb3d-d5db-4781-9bf0-d6511bc89a30","badge":"picture","interactive":false},
  {"slug":"cet-carnot-engine","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"thermodynamics","chapterName":"Thermodynamics","subtopicSlug":"cetp-td-carnot","subtopicTitle":"The Carnot Engine and the Refrigerator","conceptSlug":"cetp-td-carnot-efficiency","conceptName":"Efficiency and Coefficient of Performance","line":"The cycle is isothermal expansion at T₁, adiabatic expansion, isothermal compression at T₂, adiabatic compression. Its efficiency η = W/Q₁ = 1 − T₂/T₁, temperatures in kelvin. Lowering the sink by a known amount changes η, and the two equations fix both temperatures. For a fixed sink, a higher efficiency needs a hotter source: T₁ = T₂/(1 − η). A refrigerator moves heat from the cold side; its coefficient of performance β = T₂/(T₁ − T₂) = (1 − η)/η, so η = 1/(β + 1). With a diatomic working gas, the adiabatic volume ratio fixes T₂/T₁ = (V₁/V₂)^0.4.","pyqExampleId":"3172b3d2-4b3b-4838-b7ac-587341b0e437","badge":"picture","interactive":false},
  {"slug":"cet-shm-reference-circle","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"oscillations","chapterName":"Oscillations","subtopicSlug":"cetp-osc-kinematics","subtopicTitle":"SHM: Displacement, Velocity, Acceleration and Phase","conceptSlug":"cetp-osc-velocity-displacement","conceptName":"Velocity, Acceleration and Displacement","line":"Everything follows from v² = ω²(A² − x²) and a = −ω²x. At the mean position the speed is largest, ωA, and the acceleration zero; at the extremes the speed is zero and the acceleration ω²A. Two positions with known speeds give two equations: subtract them and A drops out, leaving ω; divide and ω drops out, leaving A. Given accelerations instead, use a = ω²x to turn them into positions. Maximum velocity and maximum acceleration together give both A = v²/a and ω = a/v.","pyqExampleId":"3b41ca29-54b0-42e7-886f-517c7a5d6d5a","badge":"try","interactive":true},
  {"slug":"osc-shm-displacement-time","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"oscillations","chapterName":"Oscillations","subtopicSlug":"cetp-osc-kinematics","subtopicTitle":"SHM: Displacement, Velocity, Acceleration and Phase","conceptSlug":"cetp-osc-phase-and-time","conceptName":"Phase, and Time to Reach a Point","line":"Write x = A sin ωt if the particle starts at the mean position, x = A cos ωt if it starts at an extreme. The phase ωt then tells you where it is: from the mean position it reaches A/2 at ωt = π/6 (T/12), A/√2 at π/4 (T/8), and the extreme at π/2 (T/4). Each full oscillation adds 2π of phase. Velocity leads displacement by π/2 and acceleration is opposite to displacement, π out of phase — so force against time is the displacement graph turned upside down.","pyqExampleId":"414cbbed-0afb-497a-a5fb-9eb45a73bea6","badge":"picture","interactive":false},
  {"slug":"osc-pendulum-restoring-force","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"oscillations","chapterName":"Oscillations","subtopicSlug":"cetp-osc-pendulum","subtopicTitle":"The Simple Pendulum: Period, Effective g, Speed and Tension","conceptSlug":"cetp-osc-pendulum-period","conceptName":"Period and Length","line":"T = 2π√(L/g): the period goes as the square root of the length and has nothing to do with the bob's mass or material. Four times the length doubles the period; frequencies 4 : 3 mean lengths 9 : 16; a 20% longer period needs 1.44 times the length. Lengths subtract as T²: a pendulum of length L₁ − L₂ has period √(T₁² − T₂²). The length is measured to the bob's centre of mass, so a leaking bob first lengthens its pendulum and then, once nearly empty, shortens it back.","pyqExampleId":"c26bd624-b383-4607-afa6-b976bf525bf2","badge":"picture","interactive":false},
  {"slug":"cet-standing-wave-modes","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"superposition-of-waves","chapterName":"Superposition of Waves","subtopicSlug":"cetp-stationary-waves","subtopicTitle":"Stationary Waves and Vibrating Strings","conceptSlug":"cetp-standing-wave-basics","conceptName":"Nodes, Antinodes and the Standing-Wave Equation","line":"In a stationary wave nothing travels: some points (nodes) never move and those halfway between (antinodes) swing hardest. Neighbouring nodes are half a wavelength apart, which is also the length of one loop.","pyqExampleId":"df406ca3-7ef3-4b9b-a83a-3d1fab0136b4","badge":"try","interactive":true},
  {"slug":"cet-pipe-modes","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"superposition-of-waves","chapterName":"Superposition of Waves","subtopicSlug":"cetp-pipes-doppler","subtopicTitle":"Organ Pipes, the Resonance Tube and the Doppler Effect","conceptSlug":"cetp-organ-pipes","conceptName":"Open and Closed Pipes","line":"An open end is free, so it is an antinode; a closed end is blocked, so it is a node. An open pipe fits half a wavelength and all its multiples; a closed pipe fits only a quarter-wavelength and its odd multiples — so it is an octave lower and missing every even harmonic.","pyqExampleId":"3c8cb748-931f-414d-bdb6-79bedae1e301","badge":"picture","interactive":false},
  {"slug":"cet-beats-envelope","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"superposition-of-waves","chapterName":"Superposition of Waves","subtopicSlug":"cetp-beats","subtopicTitle":"Beats, and Tuning a Sonometer","conceptSlug":"cetp-beat-frequency","conceptName":"Beat Frequency, Timing and Loudness","line":"Two tones a few hertz apart come back into step that many times each second. Loud moments (waxing) are 1/Δf apart, and the quiet moment falls halfway between. The loudest sound has amplitude a₁ + a₂, the quietest a₁ − a₂.","pyqExampleId":"53335e07-6251-4e53-9c4d-61972ebc60bd","badge":"try","interactive":true},
  {"slug":"cet-ydse-fringe-width","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"wave-optics","chapterName":"Wave Optics","subtopicSlug":"cetp-ydse-fringes","subtopicTitle":"Young's Double Slit: Fringe Width, Fringe Positions and Shifts","conceptSlug":"cetp-fringe-width","conceptName":"Fringe Width","line":"Fringes are spaced by the distance over which the path difference grows by one wavelength. A longer wavelength or a farther screen spreads them out; wider-set slits crowd them in. In water the wavelength shrinks by μ, and so does the fringe width.","pyqExampleId":"3b3bdff8-06a0-416f-b481-1cd6f8cfcfab","badge":"try","interactive":true},
  {"slug":"jee-malus-polaroids","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"wave-optics","chapterName":"Wave Optics","subtopicSlug":"cetp-polarisation","subtopicTitle":"Polarisation: Malus' Law and Brewster's Law","conceptSlug":"cetp-malus","conceptName":"Malus' Law and Chains of Polaroids","line":"The first polaroid throws away half of unpolarised light whatever its angle. After that the light is polarised, and each polaroid passes the fraction cos²θ, θ being the angle between its axis and the previous one's. Crossed polaroids pass nothing, but slip a third one between them and light gets through.","pyqExampleId":"e3c5d166-a0a0-43c2-a88e-8256c4f3c566","badge":"try","interactive":true},
  {"slug":"field-lines-charge","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"electrostatics","chapterName":"Electrostatics","subtopicSlug":"cetp-coulomb-field","subtopicTitle":"Coulomb's Law and Electric Field","conceptSlug":"cetp-field-superposition","conceptName":"Superposition: Symmetric Arrangements and Field Lines","line":"At the centre of a regular shape, equal charges on opposite vertices cancel each other's fields. Strip out every cancelling pair and only one or two charges are left to compute. Potential does not cancel this way — it is a plain sum — so a point can have zero field and non-zero potential, or the reverse.","pyqExampleId":"5a272475-5846-46f6-b227-1c8225bbbc1a","badge":"picture","interactive":false},
  {"slug":"cet-dipole-torque","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"electrostatics","chapterName":"Electrostatics","subtopicSlug":"cetp-dipole","subtopicTitle":"Electric Dipole — Field, Potential and Torque","conceptSlug":"cetp-dipole-torque-energy","conceptName":"Torque, Energy and Work for a Dipole in a Uniform Field","line":"In a uniform field the forces on +q and −q are equal and opposite, so the dipole does not move off but it turns, trying to line up with the field. Lined up, its energy is lowest (−pE); turned right round it is highest (+pE). The work to turn it is the rise in that energy.","pyqExampleId":"9d76b3e1-58a5-452d-80e0-fe97aeaec28a","badge":"try","interactive":true},
  {"slug":"neet-capacitor-dielectric","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"electrostatics","chapterName":"Electrostatics","subtopicSlug":"cetp-dielectrics","subtopicTitle":"Dielectrics in Capacitors","conceptSlug":"cetp-dielectric-slab","conceptName":"A Slab Filling Part of the Gap","line":"A slab of thickness t and constant K acts like a thinner layer of air, t/K thick. So the capacitor behaves as if its gap had shrunk by t(1 − 1/K). A metal sheet is the limit K → ∞: it simply removes its own thickness from the gap.","pyqExampleId":"917aee47-1ce4-4031-b49d-71b29c19cd69","badge":"try","interactive":true},
  {"slug":"emf-internal-resistance","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"current-electricity","chapterName":"Current Electricity","subtopicSlug":"cetp-ce-cells","subtopicTitle":"E.m.f., Internal Resistance and Cells Together","conceptSlug":"cetp-ce-emf-internal-resistance","conceptName":"Terminal Voltage and Cells in Series or Parallel","line":"A real cell is an ideal e.m.f. E with a small resistance r inside it. With current I flowing, the terminals show V = E − Ir, less than E by the drop inside. A voltmeter of resistance R_V across a cell reads E·R_V/(R_V + r), which is how r is found from a reading. Two cells in series driving R carry I = (E₁ + E₂)/(R + r₁ + r₂); one of them shows zero terminal voltage when its own drop Ir equals its E. Two unequal cells in parallel settle at a common voltage that is the resistance-weighted mean of their e.m.f.s. In the steady state a capacitor carries no current, so its branch drops out of the current calculation but it still charges to the voltage across it.","pyqExampleId":"87dfcc37-ea62-4f54-beae-bc570f612259","badge":"picture","interactive":false},
  {"slug":"cet-metre-bridge","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"current-electricity","chapterName":"Current Electricity","subtopicSlug":"cetp-ce-bridges","subtopicTitle":"The Wheatstone Bridge and the Metre Bridge","conceptSlug":"cetp-ce-meter-bridge","conceptName":"The Metre Bridge and its Null Point","line":"The metre bridge replaces two arms with a 100 cm uniform wire. Resistance of the wire is proportional to length, so at the null point l cm from the left end the unknown in the left gap satisfies X/R = l/(100 − l). Everything follows from that one line: swapping the resistances moves the null point from l to 100 − l; doubling both changes nothing, so doubling and swapping gives 100 − l; a thicker or longer wire of the same material also changes nothing because only the ratio of lengths enters. Shunting one gap lowers its resistance, and the null point moves away from it.","pyqExampleId":"4613dac4-2cbc-47c7-ba1e-083964cf3268","badge":"picture","interactive":false},
  {"slug":"magnetic-force-triad","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"magnetic-fields-due-to-electric-current","chapterName":"Magnetic Fields Due to Electric Current","subtopicSlug":"cetp-mag-moving-charge","subtopicTitle":"Force on a Moving Charge, and Circular Motion in a Field","conceptSlug":"cetp-mag-lorentz-force","conceptName":"The Magnetic Force on a Moving Charge","line":"F = q(v × B): the force is perpendicular to the velocity, so it can turn the charge but never speed it up or slow it down — the work it does is always zero. Its size is qvB sin θ, so a charge moving along the field lines feels nothing. Work the cross product component by component when v and B are given as vectors. With an electric field too, the total is the Lorentz force qE + q(v × B). A cyclotron uses the magnetic force to bend and an alternating electric field to accelerate, so it works for any charged particle, positive or negative — but not for neutrons.","pyqExampleId":"536eb23e-3a0f-4571-9d50-09e38597ba8e","badge":"try","interactive":true},
  {"slug":"flemings-left-hand-rule","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"magnetic-fields-due-to-electric-current","chapterName":"Magnetic Fields Due to Electric Current","subtopicSlug":"cetp-mag-force-on-conductor","subtopicTitle":"Force on a Current-Carrying Wire, and Between Parallel Wires","conceptSlug":"cetp-mag-force-on-wire","conceptName":"Force on a Straight Conductor","line":"F = I(L × B), of size ILB sin θ where θ is the angle between the wire and the field. For a field given as a vector, work the cross product; only the parts of B across the wire count. A closed loop in a UNIFORM field feels no net force, but near a long straight wire the field is not uniform: the side nearer the wire feels a stronger push than the far side, and the sides perpendicular to the wire cancel.","pyqExampleId":"2ec23e7d-52b0-4f7c-8434-6cdc38298a66","badge":"try","interactive":true},
  {"slug":"magnetic-field-around-wire","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"magnetic-fields-due-to-electric-current","chapterName":"Magnetic Fields Due to Electric Current","subtopicSlug":"cetp-mag-field-of-current","subtopicTitle":"Magnetic Field of Wires, Coils, Arcs, Solenoids and Toroids","conceptSlug":"cetp-mag-straight-wire-field","conceptName":"Field of Straight Wires","line":"A long straight wire's field circles it with B = μ₀I/(2πd), falling as 1/d. With two wires, find each field's direction by the right-hand rule and add as vectors. Midway between them, like currents give OPPOSITE fields (they subtract, zero if equal) and opposite currents give fields in the SAME direction (they add). At a point where the lines to the two wires are perpendicular, the fields are perpendicular too, so add them by Pythagoras. Inside a thick wire the field rises linearly from zero, μ₀Ir/(2πR²); outside it falls as 1/r.","pyqExampleId":"921e29d6-f7ca-4b53-975c-a9bfd1777cfc","badge":"picture","interactive":false},
  {"slug":"cet-hysteresis-loop","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"magnetic-materials","chapterName":"Magnetic Materials","subtopicSlug":"cetp-mm-classification","subtopicTitle":"Dia-, Para- and Ferromagnets, Hysteresis and Shielding","conceptSlug":"cetp-mm-hysteresis-shielding","conceptName":"Hysteresis, Electromagnets and Shielding","line":"Only ferromagnets show hysteresis: their B lags behind H round a loop. When H falls to zero, the B that remains is the retentivity; the reverse H needed to bring B to zero is the coercivity. Soft iron has a high retentivity but a low coercivity, so it is easy to magnetise and demagnetise — right for electromagnets. A permanent magnet needs both high. A soft ferromagnet around an instrument draws the field lines into itself and shields the inside.","pyqExampleId":"4893185b-255d-4727-9b18-3719e382d54f","badge":"try","interactive":true},
  {"slug":"cet-lenz-magnet-coil","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"electromagnetic-induction","chapterName":"Electromagnetic Induction","subtopicSlug":"cetp-emi-faraday-lenz","subtopicTitle":"Faraday's Law, Lenz's Law and Induced Charge","conceptSlug":"cetp-emi-lenz","conceptName":"Lenz's Law: the Induced Current Opposes the Change","line":"The induced current always pushes back against whatever changes the flux. A magnet falling through a closed ring is braked, so it falls with less than g; a hollow metal pipe does the same through eddy currents. A ring with a CUT carries no current, so the magnet falls freely at g. A ring falling towards a wire whose field points out of the page above it sees that outward flux grow, so its current makes an inward field — clockwise. And if the coil and magnet move together, nothing changes and nothing is induced. This opposition is why Lenz's law is the law of conservation of energy in disguise: you must do work to push against it.","pyqExampleId":"ac369739-24df-41a1-9d5e-827f783e33e2","badge":"try","interactive":true},
  {"slug":"cet-rotating-rod-emf","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"electromagnetic-induction","chapterName":"Electromagnetic Induction","subtopicSlug":"cetp-emi-motional","subtopicTitle":"Motional e.m.f., Magnetic Braking and Rotating Rods","conceptSlug":"cetp-emi-rotating-rod-disc","conceptName":"Rotating Rods, Discs, Wheels and Coils","line":"A rod spinning about one end moves faster further out; its average speed is ωl/2, so e = B·l·(ωl/2) = ½Bωl². A disc is a crowd of such radii in parallel — rim to axle it is ½BωR² too; so is a bicycle wheel, however many spokes it has, since they are in parallel. A whole coil turning in a field is different: its flux varies as cos ωt, so its e.m.f. peaks at NBAω and the average power into a resistor is (NBAω)²/(2R).","pyqExampleId":"15a3301b-8fcb-4336-80b5-5239ae00dd65","badge":"picture","interactive":false},
  {"slug":"cet-lcr-phasors","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"ac-circuits","chapterName":"AC Circuits","subtopicSlug":"cetp-lcr-impedance","subtopicTitle":"Series LR, RC and LCR: Impedance, Phase and Phasors","conceptSlug":"cetp-phasor-voltages","conceptName":"Voltages Add as Phasors","line":"V_L and V_C point in opposite directions and both stand at right angles to V_R, so the supply voltage is the hypotenuse of V_R and the difference V_L − V_C. The same geometry makes the currents in a parallel L and C subtract.","pyqExampleId":"e14825ba-ff9d-4ce1-a0b2-1dbd8dfaa2ad","badge":"try","interactive":true},
  {"slug":"cet-resonance-curve","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"ac-circuits","chapterName":"AC Circuits","subtopicSlug":"cetp-resonance","subtopicTitle":"Resonance in Series LCR Circuits","conceptSlug":"cetp-resonance-behaviour","conceptName":"What Happens at Resonance","line":"At resonance the two reactances cancel, so the circuit looks like its resistor alone. Sweep the frequency upward and the impedance falls to R and rises again — so the current, and a series bulb's brightness, rise to a peak and fall.","pyqExampleId":"93934042-c9e7-404f-ae5c-593dda65aa59","badge":"try","interactive":true},
  {"slug":"cet-photoelectric-threshold","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"dual-nature-of-radiation-and-matter","chapterName":"Dual Nature of Radiation and Matter","subtopicSlug":"cetp-dn-photoelectric","subtopicTitle":"The Photoelectric Effect","conceptSlug":"cetp-dn-einstein-equation","conceptName":"Einstein's Equation in One Situation","line":"Einstein's equation balances the photon's energy against the work function and the electron's kinetic energy: hν = φ + ½mv²ₘₐₓ, and the stopping potential is that kinetic energy in electron-volts, eV₀ = ½mv²ₘₐₓ. When the photon energy is given as a multiple of φ, the kinetic energy is that multiple minus one, and speeds go as the square root: photons of 2φ and 3φ give speeds in the ratio 1 : √2. With hc = 1240 eV nm, a wavelength in nanometres converts to photon energy in eV at once.","pyqExampleId":"741d2e89-9cbe-4118-a6e8-836dccc526a4","badge":"try","interactive":true},
  {"slug":"cet-photoelectric-graphs","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"dual-nature-of-radiation-and-matter","chapterName":"Dual Nature of Radiation and Matter","subtopicSlug":"cetp-dn-photoelectric","subtopicTitle":"The Photoelectric Effect","conceptSlug":"cetp-dn-photoelectric-graphs","conceptName":"Reading the Photoelectric Graphs","line":"Photocurrent against anode potential: the current is zero at the stopping potential (on the negative side) and levels off at the saturation current (on the positive side). Where a curve meets the axis tells you the FREQUENCY — a more negative cut-off means a higher frequency — and how high it levels off tells you the INTENSITY. Stopping potential against frequency is a straight line of slope h/e for every metal; it cuts the axis at the threshold frequency, so the line further right belongs to the metal with the larger work function. Kinetic energy against frequency is the same line scaled by e, starting from the threshold.","pyqExampleId":"81bc5dee-35d9-49f5-b657-4efa56c6023f","badge":"picture","interactive":false},
  {"slug":"cet-hydrogen-series","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"structure-of-atoms-and-nuclei","chapterName":"Structure of Atoms and Nuclei","subtopicSlug":"cetp-an-spectrum","subtopicTitle":"The Hydrogen Spectrum and its Series","conceptSlug":"cetp-an-series-limits","conceptName":"The Series, Their First Lines and Their Limits","line":"Fix the lower level n_f and let the upper level run: n_f = 1 gives the Lyman series (ultraviolet), 2 the Balmer (visible), 3 the Paschen, 4 the Brackett and 5 the Pfund (all infrared). The first line comes from the nearest level, n_f + 1, and has the smallest energy, so the LONGEST wavelength. The series limit comes from n = ∞, 1/λ = R/n_f², and has the SHORTEST wavelength. Frequency is c/λ and wave number is 1/λ, so the Balmer limit has wave number R/4 and frequency Rc/4. Because limits and first lines are differences of the same terms, they combine: the Lyman limit minus the first Lyman line is the Balmer limit. A source moving away stretches every line by Δλ/λ = v/c.","pyqExampleId":"beeb5e4c-a25c-4c83-8869-c502221ee763","badge":"picture","interactive":false},
  {"slug":"imat-half-life-decay","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"structure-of-atoms-and-nuclei","chapterName":"Structure of Atoms and Nuclei","subtopicSlug":"cetp-an-nuclei","subtopicTitle":"Nuclei: Radioactive Decay and Binding Energy","conceptSlug":"cetp-an-decay-law","conceptName":"The Decay Law and Half-Life","line":"Each nucleus has the same chance λ per second of decaying, so the number left falls exponentially: N = N₀e^(−λt). After one half-life T½ = ln 2/λ half remain, after n half-lives (1/2)ⁿ. Activity, the decays per second, is A = λN and falls the same way, so two activities give λ directly: A/A₀ = e^(−λt). Two samples with decay constants λ₁ and λ₂ starting equal have N₁/N₂ = e^(−(λ₁ − λ₂)t). Read the question for 'decayed' or 'left': after 3 half-lives, 12.5% is left and 87.5% has decayed.","pyqExampleId":"d05959de-73ad-4fee-881b-89f2d0abb0a0","badge":"try","interactive":true},
  {"slug":"cet-pn-depletion","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"semiconductor-devices","chapterName":"Semiconductor Devices","subtopicSlug":"cetp-pn-junction","subtopicTitle":"The p-n Junction: Depletion Layer and Biasing","conceptSlug":"cetp-depletion-layer","conceptName":"The Depletion Layer and Its Field","line":"Electrons diffuse from the n-side into the p-side and holes the other way; they recombine and leave behind uncovered ions — positive on the n-side, negative on the p-side. Those fixed charges make a field pointing from n to p, which stops further diffusion. The n-side ends up at the higher potential.","pyqExampleId":"241fcd7e-9963-4ddd-b312-8274410c06fb","badge":"try","interactive":true},
  {"slug":"cet-diode-bias","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"semiconductor-devices","chapterName":"Semiconductor Devices","subtopicSlug":"cetp-pn-junction","subtopicTitle":"The p-n Junction: Depletion Layer and Biasing","conceptSlug":"cetp-biasing","conceptName":"Forward and Reverse Bias","line":"Push the p-side positive and the applied field opposes the junction's own: the barrier drops, the layer thins, and current flows. Push it negative and the two fields add: the barrier rises, the layer widens, and only a tiny minority-carrier current trickles through.","pyqExampleId":"e9d9b720-556b-40e5-b996-3bbd492f0c2e","badge":"picture","interactive":false},
  {"slug":"cet-rectifier-waves","examSlug":"mht-cet","examName":"MHT-CET","subjectName":"Physics","subjectRoute":"mht-cet-physics","subjectDisplay":"MHT-CET Physics","chapterSlug":"semiconductor-devices","chapterName":"Semiconductor Devices","subtopicSlug":"cetp-diode-circuits","subtopicTitle":"Diode Circuits and Rectifiers","conceptSlug":"cetp-rectifiers","conceptName":"Half-Wave and Full-Wave Rectifiers","line":"A single diode passes only one half of each cycle: half-wave output, pulsing at the supply frequency. Two diodes with a centre-tapped transformer (or a bridge) pass both halves the same way round, so the pulses come twice as often and the efficiency doubles.","pyqExampleId":"2bb303d5-8c9a-4a95-8d7a-244a4d524583","badge":"try","interactive":true},
];

